import CoreMedia
import Foundation

class EVCalculator {

    struct EVConfiguration {
        let exposuteDuration: CMTime
        let iso: Float
    }

    func calculateShutterSpeedForEVShifts(
        _ evShifts: [Double],
        andFNumber fNumber: Double,
        givenOriginalShutterSpeed originalShutterSpeed: Double,
        andISO iso: Float
    ) -> [EVConfiguration] {
        let originalEV = calculateEV(fNumber: fNumber, shutterSpeed: originalShutterSpeed)
        return evShifts.map { evShift in
            let shiftedEV = originalEV + evShift
            return EVConfiguration(
                exposuteDuration: calculateShutterSpeedForEV(
                    shiftedEV,
                    andFNumber: fNumber
                ).shutterTime,
                iso: iso
            )
        }
    }

    private func calculateShutterSpeedForEV(_ ev: Double, andFNumber fNumber: Double) -> Double {
        pow(fNumber, 2) / pow(2, ev)
    }

    private func calculateEV(fNumber: Double, shutterSpeed: Double) -> Double {
        log2(pow(fNumber, 2) / shutterSpeed)
    }
}

private extension Double {

    var shutterTime: CMTime {
        let scale: Int32 = 1000000000
        return CMTime(seconds: self, preferredTimescale: scale)
    }
}
